-- RetailHub — baza de date pentru Modulul 4 (SQL). Generată din 04_DATASETS (seed 42).
-- Încarcă o dată în MySQL: în MySQL Workbench, File > Open SQL Script > acest fișier > Execute (fulgerul).
-- Sau la linia de comandă:  mysql -u root -p < RetailHub.sql
--
-- ⚠️ ATENȚIE: prima linie de mai jos rulează `DROP DATABASE IF EXISTS retailhub;` — adică
--    ȘTERGE COMPLET orice bază de date numită `retailhub` pe care o ai deja, apoi o recreează
--    curată. Asta e intenționat (ca reîncărcarea să pornească mereu de la zero), dar dacă folosești
--    deja o bază `retailhub` pentru altceva, REDENUMEȘTE-o înainte sau schimbă numele de mai jos.
--    Nicio ALTĂ bază de date de-a ta nu e atinsă — doar `retailhub`.

DROP DATABASE IF EXISTS retailhub;
CREATE DATABASE retailhub CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE retailhub;
SET FOREIGN_KEY_CHECKS=0;

-- ---------- categories ----------
DROP TABLE IF EXISTS categories;
CREATE TABLE categories (
  CategoryID INT,
  CategoryName VARCHAR(50) NOT NULL,
  PRIMARY KEY (CategoryID)
) ENGINE=InnoDB;

-- ---------- stores ----------
DROP TABLE IF EXISTS stores;
CREATE TABLE stores (
  StoreID INT,
  StoreName VARCHAR(100) NOT NULL,
  City VARCHAR(50) NOT NULL,
  Region VARCHAR(50),
  OpeningDate DATE,
  PRIMARY KEY (StoreID)
) ENGINE=InnoDB;

-- ---------- products ----------
DROP TABLE IF EXISTS products;
CREATE TABLE products (
  ProductID INT,
  ProductName VARCHAR(100) NOT NULL,
  CategoryID INT,
  Brand VARCHAR(50),
  Cost DECIMAL(12,2),
  Price DECIMAL(12,2),
  Status VARCHAR(20),
  PRIMARY KEY (ProductID),
  FOREIGN KEY (CategoryID) REFERENCES categories(CategoryID)
) ENGINE=InnoDB;

-- ---------- customers ----------
DROP TABLE IF EXISTS customers;
CREATE TABLE customers (
  CustomerID INT,
  FirstName VARCHAR(50),
  LastName VARCHAR(50),
  Gender VARCHAR(10),
  BirthDate DATE,
  City VARCHAR(50),
  RegistrationDate DATE,
  LoyaltyLevel VARCHAR(20),
  PRIMARY KEY (CustomerID)
) ENGINE=InnoDB;

-- ---------- employees ----------
DROP TABLE IF EXISTS employees;
CREATE TABLE employees (
  EmployeeID INT,
  FirstName VARCHAR(50),
  LastName VARCHAR(50),
  Position VARCHAR(50),
  Department VARCHAR(50),
  StoreID INT,
  PRIMARY KEY (EmployeeID),
  FOREIGN KEY (StoreID) REFERENCES stores(StoreID)
) ENGINE=InnoDB;

-- ---------- campaigns ----------
DROP TABLE IF EXISTS campaigns;
CREATE TABLE campaigns (
  CampaignID INT,
  CampaignName VARCHAR(100),
  Channel VARCHAR(30),
  StartDate DATE,
  EndDate DATE,
  Budget DECIMAL(12,2),
  PRIMARY KEY (CampaignID)
) ENGINE=InnoDB;

-- ---------- orders ----------
DROP TABLE IF EXISTS orders;
CREATE TABLE orders (
  OrderID INT,
  OrderDate DATE NOT NULL,
  CustomerID INT,
  StoreID INT,
  EmployeeID INT,
  CampaignID INT,
  TotalAmount DECIMAL(12,2),
  Discount DECIMAL(10,2),
  PaymentMethod VARCHAR(20),
  PRIMARY KEY (OrderID),
  FOREIGN KEY (CustomerID) REFERENCES customers(CustomerID),
  FOREIGN KEY (StoreID) REFERENCES stores(StoreID),
  FOREIGN KEY (EmployeeID) REFERENCES employees(EmployeeID),
  FOREIGN KEY (CampaignID) REFERENCES campaigns(CampaignID)
) ENGINE=InnoDB;

-- ---------- order_items ----------
DROP TABLE IF EXISTS order_items;
CREATE TABLE order_items (
  OrderItemID INT,
  OrderID INT,
  ProductID INT,
  Quantity INT,
  UnitPrice DECIMAL(12,2),
  PRIMARY KEY (OrderItemID),
  FOREIGN KEY (OrderID) REFERENCES orders(OrderID),
  FOREIGN KEY (ProductID) REFERENCES products(ProductID)
) ENGINE=InnoDB;

-- ---------- inventory ----------
DROP TABLE IF EXISTS inventory;
CREATE TABLE inventory (
  InventoryID INT,
  StoreID INT,
  ProductID INT,
  StockQuantity INT,
  ReorderLevel INT,
  LastUpdated DATE,
  PRIMARY KEY (InventoryID),
  FOREIGN KEY (StoreID) REFERENCES stores(StoreID),
  FOREIGN KEY (ProductID) REFERENCES products(ProductID)
) ENGINE=InnoDB;

SET FOREIGN_KEY_CHECKS=1;
-- Gata. Verificare rapidă:  SELECT COUNT(*) FROM orders;  -> 14968